function TROP_POLY_EVAL(c[0..d], x):
    best_i <- 0
    best_v <- c[0] + 0*x
    for i = 1 to d:
        v <- c[i] + i*x
        if v > best_v:
            best_i <- i
            best_v <- v
    return (best_v, best_i)   // best_v = tropPoly_c(x), attained at best_i

