function TROPICAL_CORNERS(c[0..d]):
    pts <- [(i, -c[i]) for i = 0..d]
    hull <- empty stack
    for p in pts:
        while |hull| >= 2 and cross(hull[-2], hull[-1], p) <= 0:
            pop hull
        push p onto hull
    return [(hull[k].i, hull[k+1].i) for k = 0 .. |hull|-2]
